import sys, json

after = json.load(sys.stdin)
json.dump(after, open('after-cpm-packages.json', 'w'), indent=2)

baseline = json.load(open('baseline-packages.json'))

# Compare
def get_pkg_map(data):
    result = {}
    for proj in data['projects']:
        name = proj['path'].split('/')[-1]
        for fw in proj['frameworks']:
            for pkg in fw['topLevelPackages']:
                key = (name, fw['framework'], pkg['id'])
                result[key] = pkg['resolvedVersion']
    return result

b = get_pkg_map(baseline)
a = get_pkg_map(after)

changes = []
for k in sorted(set(list(b.keys()) + list(a.keys()))):
    bv = b.get(k, 'MISSING')
    av = a.get(k, 'MISSING')
    if bv != av:
        changes.append((k, bv, av))

if changes:
    print('VERSION CHANGES:')
    for (proj, fw, pkg), bv, av in changes:
        print(f'  {proj} ({fw}): {pkg} {bv} -> {av}')
else:
    print('No version changes - but checking for new packages...')

# Check added/removed
for k in sorted(set(a.keys()) - set(b.keys())):
    print(f'  ADDED: {k[0]} ({k[1]}): {k[2]} = {a[k]}')
for k in sorted(set(b.keys()) - set(a.keys())):
    print(f'  REMOVED: {k[0]} ({k[1]}): {k[2]} = {b[k]}')
"

